package main

import "slices"

type clipKind int

const (
	clipSkip clipKind = iota
	clipText
	clipImage
)

// privateClipTypes are the nspasteboard.org markers password managers and
// similar sources set to ask clipboard history tools not to record a copy.
var privateClipTypes = []string{
	"org.nspasteboard.ConcealedType",
	"org.nspasteboard.TransientType",
	"org.nspasteboard.AutoGeneratedType",
	"com.agilebits.onepassword",
	"de.petermaurer.TransientPasteboardType",
	"net.antelle.keeweb",
}

var (
	clipTextTypes  = []string{"public.utf8-plain-text", "public.utf16-plain-text", "NSStringPboardType"}
	clipImageTypes = []string{"public.png", "public.tiff", "NSTIFFPboardType"}
)

// classifyClipboard decides what a clipboard change should add, from the
// pasteboard's declared types in the source's order of preference.
// Finder file copies are skipped: their image is only the file icon and
// their text only the file name. When both text and an image are offered
// (Office, Numbers, web pages), the representation the source lists
// first wins, so a spreadsheet copy is kept as text and a copied picture
// as an image.
func classifyClipboard(types []string) clipKind {
	for _, t := range types {
		if slices.Contains(privateClipTypes, t) {
			return clipSkip
		}
	}
	if slices.Contains(types, "public.file-url") || slices.Contains(types, "NSFilenamesPboardType") {
		return clipSkip
	}
	for _, t := range types {
		switch {
		case slices.Contains(clipTextTypes, t):
			return clipText
		case slices.Contains(clipImageTypes, t):
			return clipImage
		}
	}
	return clipSkip
}
